INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'mandatory_bundle', 'ต้องซื้อสองรหัสพร้อมกัน', 'Mandatory combined purchase', '3A0424 ราคา 316,424,000 บาท + 3A1498 ราคา 387,200 บาท รวม 316,811,200 บาท ผู้ซื้อคนเดียวกันเสนอพร้อมกัน', 'Same buyer must offer for both assets simultaneously; combined minimum THB 316,811,200', 'unspecified', 10) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'equipment_vat', 'VAT อุปกรณ์เพิ่มเติม', 'Additional equipment VAT', 'ราคาอุปกรณ์ 387,200 บาทยังไม่รวม VAT ผู้ซื้อชำระทั้งจำนวน', 'Equipment THB 387,200 excludes VAT, fully payable by buyer', 'unspecified', 20) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'closed_incomplete', 'หยุดกิจการและก่อสร้างไม่ครบ', 'Closed and incomplete', 'โรงแรมทรุดโทรม สำรวจแล้วเสร็จประมาณ 80% อาคารสระว่ายน้ำประมาณ 21%', 'Closed, dilapidated; hotel approx 80% complete, pool building 21%', 'unspecified', 30) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'boundary_survey', 'ต้องรังวัดสอบเขต', 'Boundary survey required', 'น.ส.3 ไม่มีตำแหน่งในระวาง แนวเหนือเกี่ยวข้องกับที่ราชพัสดุ/โบราณสถาน เนื้อที่อาจเปลี่ยนอย่างมีนัยสำคัญ', 'NS3 unplotted; northern government/historic-site boundary uncertain; area may change materially', 'unspecified', 40) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'equipment_inventory', 'ตรวจนับสังหาริมทรัพย์', 'Verify equipment inventory', '584 รายการตามเอกสารปี 2557 ขายตามสภาพและรายการที่ตรวจพบ ไม่รับรองจำนวนหรือสภาพปัจจุบัน', 'Historic 2014 inventory of 584; as-is, verify current existence and condition', 'unspecified', 50) ;
