INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=20241&keyref=', '3A0424', now(), 'Official page checked 2026-09-15. Displayed price sums mandatory bundle 3A0424 THB316424000 and 3A1498 THB387200; equipment VAT extra payable by buyer. Closed hotel, 253 surveyed rooms, incomplete/dilapidated. NS3 boundary and material area uncertainty disclosed. Historic 584-item equipment inventory unconfirmed today. 29 authentic images; surrounding park not asserted included. No all-status duplicate matches by both references, page, title/deed and nearby coordinates.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Saeng Rung Interpark Hotel, Buriram — Closed Hotel and Mandatory Equipment Package', 'Saeng Rung Interpark Hotel, 38 Moo 1, Isan, Mueang Buri Ram, Buri Ram, on Buri Ram Bypass Highway 288. A 13-storey hotel with basement and mezzanine; survey reports 253 guest rooms. Four adjoining plots total 19 rai 2 ngan 97.1 sq.wah (31,588.4 sq.m.), comprising Chanote 3331 and Nor Sor 3 certificates 207, 281 and 282.
